package com.hbm.machine.pa.cooled;
import api.hbm.redstoneoverradio.IRORValueProvider;
import com.hbm.api.computer.*;
import com.hbm.api.machine.MachineView;
import com.hbm.energy.*;
import com.hbm.fluid.*;
import com.hbm.fluid.network.*;
import com.hbm.item.battery.*;
import com.hbm.multiblock.*;
import java.math.BigInteger;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
/** Exact source CooledBase shared by all5actual PA machines, private native fluid/HE only. */
public abstract class PaCooledEntity extends BlockEntity implements WorldlyContainer,MenuProvider,NamedMultiblock,EnergyReceiver,SidedEnergyConnector,StandardFluidTransceiver,MachineView,MuffledMachine,ComputerControl,IRORValueProvider{
    public static final float KELVIN=273F,TARGET=KELVIN-150F,TEMP_PER_MB=.5F,PASSIVE_HEATING=2.5F,MAX_CHANGE=5F+PASSIVE_HEATING;
    public final PaKind kind;protected final ItemStack[] slots;public final FluidTank[] coolantTanks={new FluidTank(HbmFluids.fromName("PERFLUOROMETHYL_COLD"),4000),new FluidTank(HbmFluids.fromName("PERFLUOROMETHYL"),4000)};public float temperature=KELVIN+20;private BigInteger power=BigInteger.ZERO;private boolean muffled;private Component customName;private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();private final Map<BlockPos,FluidPorts> fluids=new LinkedHashMap<>();private List<PaPorts.Port> connected=List.of();
    protected PaCooledEntity(BlockEntityType<?> type,PaKind kind,BlockPos pos,BlockState state){super(type,pos,state);this.kind=kind;slots=new ItemStack[kind.slots];Arrays.fill(slots,ItemStack.EMPTY);}
    @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
    public List<PaPorts.Port> ports(){return PaPorts.positions(kind,worldPosition,DummyableBlock.facing(getBlockState()));}public boolean portConnects(BlockPos pos,Direction side){return side!=null&&ports().stream().anyMatch(port->port.position().equals(pos)&&port.side()==side);}
    public void control(CompoundTag tag){}protected void beforeCooling(ServerLevel level){}protected void writeState(CompoundTag tag,HolderLookup.Provider lookup){}protected void readState(CompoundTag tag,HolderLookup.Provider lookup){}protected void writeSnapshot(CompoundTag tag){}protected void readSnapshot(CompoundTag tag){}
    public static void tick(Level level,BlockPos pos,BlockState state,PaCooledEntity machine){if(!(level instanceof ServerLevel server))return;machine.updatePorts(server);machine.chargeBattery();machine.beforeCooling(server);machine.temperature+=PASSIVE_HEATING;if(machine.temperature>KELVIN+20)machine.temperature=KELVIN+20;if(machine.temperature>TARGET){int cyclesTemp=(int)Math.ceil(Math.min(machine.temperature-TARGET,MAX_CHANGE)/TEMP_PER_MB);int cycles=Math.min(cyclesTemp,Math.min(machine.coolantTanks[0].getFill(),machine.coolantTanks[1].getMaxFill()-machine.coolantTanks[1].getFill()));machine.coolantTanks[0].setFill(machine.coolantTanks[0].getFill()-cycles);machine.coolantTanks[1].setFill(machine.coolantTanks[1].getFill()+cycles);machine.temperature-=TEMP_PER_MB*cycles;}var snapshot=machine.getUpdateTag(server.registryAccess());var packet=ClientboundBlockEntityDataPacket.create(machine,(ignored,lookup)->snapshot);for(var player:server.players())if(player.distanceToSqr(pos.getX(),pos.getY(),pos.getZ())<2500)player.connection.send(packet);machine.setChanged();}
    public boolean isCool(){return temperature<=TARGET;}protected boolean hasPower(long amount){return power.compareTo(BigInteger.valueOf(amount))>=0;}protected void usePower(long amount){power=power.subtract(BigInteger.valueOf(amount));setChanged();}
    private void chargeBattery(){var capacity=getMaxPowerExact();if(power.signum()<0){power=BigInteger.ZERO;return;}if(power.compareTo(capacity)>0){power=capacity;return;}if(slots[0].getItem() instanceof CreativeBatteryItem){power=capacity;return;}if(slots[0].getItem() instanceof HbmBattery battery){long amount=Math.min(Math.min(capacity.subtract(power).longValueExact(),battery.getDischargeRate(slots[0])),battery.getCharge(slots[0]));battery.dischargeBattery(slots[0],amount);power=power.add(BigInteger.valueOf(amount));}}
    private void updatePorts(ServerLevel server){var current=new ArrayList<PaPorts.Port>();for(var port:ports())if(server.hasChunkAt(port.position())&&server.getBlockState(port.position()).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(port.position())))current.add(port);if(!current.equals(connected)||nodes.values().stream().anyMatch(PowerNode::isExpired)){disconnect();connected=List.copyOf(current);for(var port:current){var connection=new NodeConnection(port.position().relative(port.side()),port.side());var node=new PowerNode(port.position()).setConnections(connection);HbmEnergy.nodespace(server).createNode(node);nodes.put(port.position(),node);fluids.put(port.position(),new FluidPorts(new BlockPos[]{port.position()},new NodeConnection[]{connection}));}}for(var fluid:fluids.values())fluid.update(server,this);for(var node:nodes.values())if(node.hasValidNet())node.addReceiver(this);}
    private void disconnect(){if(level instanceof ServerLevel server){for(var node:nodes.values())HbmEnergy.nodespace(server).destroyNode(node);for(var fluid:fluids.values())fluid.remove(server);}nodes.clear();fluids.clear();connected=List.of();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
    @Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null&&(kind!=PaKind.DIPOLE||side.getAxis()==Direction.Axis.Y);}@Override public boolean canConnect(HbmFluidType type,Direction side){return canConnect(side);}
    @Override public long getPower(){return power.longValueExact();}@Override public long getMaxPower(){return kind.capacity;}@Override public void setPower(long value){setPowerExact(BigInteger.valueOf(value));}@Override public BigInteger getPowerExact(){return power;}@Override public BigInteger getMaxPowerExact(){return BigInteger.valueOf(kind.capacity);}@Override public void setPowerExact(BigInteger value){power=value;setChanged();}
    @Override public FluidTank[] getAllTanks(){return coolantTanks;}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{coolantTanks[0]};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{coolantTanks[1]};}@Override public long getProviderSpeed(HbmFluidType type,int pressure){return 1000000000L;}@Override public long getReceiverSpeed(HbmFluidType type,int pressure){return 1000000000L;}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rejected=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(rejected!=amount)setChanged();return rejected;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);if(amount>0)setChanged();}
    @Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return kind.capacity;}@Override public List<TankView> tanks(){return Arrays.stream(coolantTanks).map(tank->new TankView(tank.getTankType(),tank.getFill(),tank.getMaxFill())).toList();}@Override public List<ProgressView> progressBars(){return List.of(new ProgressView("jade.hbm.pa.cooling",KELVIN+20-temperature,KELVIN+20-TARGET,0x71c7e8));}
    @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}@Override public void setCustomName(Component name){customName=name;setChanged();}@Override public Component getDisplayName(){return customName!=null?customName:Component.translatable(kind.title);}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new PaMenu(kind,id,inventory,this,worldPosition);}
    private void commonSave(CompoundTag tag){tag.putLong("power",getPower());tag.putString("powerExact",power.toString());tag.putFloat("temperature",temperature);coolantTanks[0].writeToNBT(tag,"t0");coolantTanks[1].writeToNBT(tag,"t1");tag.putBoolean("muffled",muffled);}private void commonLoad(CompoundTag tag){power=tag.contains("powerExact")?new BigInteger(tag.getString("powerExact")):BigInteger.valueOf(tag.getLong("power"));temperature=tag.getFloat("temperature");coolantTanks[0].readFromNBT(tag,"t0");coolantTanks[1].readFromNBT(tag,"t1");muffled=tag.getBoolean("muffled");}
    @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var items=NonNullList.withSize(slots.length,ItemStack.EMPTY);for(int i=0;i<slots.length;i++)items.set(i,slots[i]);ContainerHelper.saveAllItems(tag,items,lookup);commonSave(tag);writeState(tag,lookup);if(customName!=null)tag.putString("CustomName",Component.Serializer.toJson(customName,lookup));}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);var items=NonNullList.withSize(slots.length,ItemStack.EMPTY);ContainerHelper.loadAllItems(tag,items,lookup);for(int i=0;i<slots.length;i++)slots[i]=items.get(i);commonLoad(tag);readState(tag,lookup);if(tag.contains("CustomName"))customName=Component.Serializer.fromJson(tag.getString("CustomName"),lookup);}
    @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();commonSave(tag);writeSnapshot(tag);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){commonLoad(tag);readSnapshot(tag);}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
    @Override public int getContainerSize(){return slots.length;}@Override public boolean isEmpty(){return Arrays.stream(slots).allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots[slot];}@Override public ItemStack removeItem(int slot,int count){var result=slots[slot].split(count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){var result=slots[slot];slots[slot]=ItemStack.EMPTY;return result;}@Override public void setItem(int slot,ItemStack stack){slots[slot]=stack;setChanged();}@Override public void clearContent(){Arrays.fill(slots,ItemStack.EMPTY);setChanged();}@Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this&&player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}
    @Override public int getMaxStackSize(){return kind==PaKind.SOURCE?1:64;}@Override public boolean canPlaceItem(int slot,ItemStack stack){return kind!=PaKind.SOURCE&&kind!=PaKind.DETECTOR||slot==1||slot==2;}@Override public int[] getSlotsForFace(Direction side){if(kind==PaKind.SOURCE)return new int[]{3,4};if(kind==PaKind.DETECTOR)return new int[]{1,2,3,4};return java.util.stream.IntStream.range(0,slots.length).toArray();}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return canPlaceItem(slot,stack);}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return kind!=PaKind.SOURCE&&kind!=PaKind.DETECTOR||slot==3||slot==4;}
    public int[] accessibleAt(BlockPos port,Direction side){return getSlotsForFace(side);}public boolean inventoryProxy(){return kind==PaKind.SOURCE||kind==PaKind.DETECTOR;}
    protected Object[] craftingInfo(){Object[] items={"",0,"",0,"",0,"",0};for(int i=0;i<4;i++){var stack=slots[i+1];if(!stack.isEmpty()){items[i*2]=stack.getDescriptionId();items[i*2+1]=stack.getCount();}}return items;}
    @Override public String computerType(){return switch(kind){case SOURCE->"ntm_pa_source";case RFC->"ntm_pa_rfc";case QUADRUPOLE->"ntm_pa_quad";case DIPOLE->"ntm_pa_dipole";case DETECTOR->"ntm_pa_detector";};}@Override public String[] computerMethods(){return new String[]{"getEnergyInfo","getCoolant","getInfo"};}protected Object[] coolantInfo(){return new Object[]{coolantTanks[0].getFill(),coolantTanks[0].getMaxFill(),coolantTanks[1].getFill(),coolantTanks[1].getMaxFill()};}protected Object[] basicInfo(){return new Object[]{getPower(),getMaxPower(),coolantTanks[0].getFill(),coolantTanks[0].getMaxFill(),coolantTanks[1].getFill(),coolantTanks[1].getMaxFill()};}@Override public Object[] callComputer(String method,ComputerArguments args)throws ComputerException{return switch(method){case "getEnergyInfo"->new Object[]{getPower(),getMaxPower()};case "getCoolant"->coolantInfo();case "getInfo"->basicInfo();default->throw new ComputerException("No such method: "+method);};}
    @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"temperature",PREFIX_VALUE+"pfmcold",PREFIX_VALUE+"pfm"};}@Override public String provideRORValue(String name){return switch(name){case PREFIX_VALUE+"temperature"->Integer.toString((int)temperature);case PREFIX_VALUE+"pfmcold"->Integer.toString(coolantTanks[0].getFill());case PREFIX_VALUE+"pfm"->Integer.toString(coolantTanks[1].getFill());default->null;};}
}
